#include "autoupdatechecker.h"

#include <QCoreApplication>
#include <QDesktopServices>
#include <QDir>
#include <QFileInfo>
#include <QJsonArray>
#include <QJsonDocument>
#include <QJsonObject>
#include <QNetworkReply>
#include <QProcess>
#include <QTemporaryFile>
#include <QUrl>

#ifdef Q_OS_WIN32
#define WIN32_LEAN_AND_MEAN
#include <Windows.h>
#include <shellapi.h>
#endif

// Generated by app.pro. The nightly workflow passes the commit it builds through
// NORILIGHT_BUILD_SHA; local builds have an empty one and never look for updates.
#include "buildversion.h"

static const char* k_NightlyReleaseUrl =
        "https://api.github.com/repos/Nori-Oppi/Norilight/releases/tags/nightly";
static const char* k_NightlyReleasePage =
        "https://github.com/Nori-Oppi/Norilight/releases/tag/nightly";

#if defined(Q_OS_WIN32)
// Waits for Norilight to close, copies the extracted ZIP over the portable
// folder and starts it again. portable.dat is left as the user had it, and
// settings are untouched because the ZIP doesn't contain any.
static const char* k_PortableUpdateScript = R"PS1(
param([int]$WaitPid, [string]$Zip, [string]$Dest, [string]$Exe)
$ErrorActionPreference = 'Stop'
$work = Split-Path -Parent $Zip
Start-Transcript -Path (Join-Path $work 'update.log') -Force | Out-Null
try {
    $app = Get-Process -Id $WaitPid -ErrorAction SilentlyContinue
    if ($app) { $app.WaitForExit(120000) | Out-Null }

    $stage = Join-Path $work 'staged'
    if (Test-Path -LiteralPath $stage) { Remove-Item -LiteralPath $stage -Recurse -Force }
    New-Item -ItemType Directory -Path $stage | Out-Null

    # tar (built into Windows 10 and later) is much faster than Expand-Archive
    & tar.exe -xf $Zip -C $stage
    if ($LASTEXITCODE -ne 0) { Expand-Archive -LiteralPath $Zip -DestinationPath $stage -Force }

    $src = $stage
    if (!(Test-Path -LiteralPath (Join-Path $src 'Norilight.exe'))) {
        $sub = Get-ChildItem -LiteralPath $stage -Directory | Where-Object { Test-Path -LiteralPath (Join-Path $_.FullName 'Norilight.exe') } | Select-Object -First 1
        if (!$sub) { throw 'The download does not contain Norilight.exe.' }
        $src = $sub.FullName
    }

    # Streams opened from the main window may take a moment to close, so retry locked files
    & robocopy.exe $src $Dest /E /R:15 /W:1 /XF portable.dat portable.dat.inactive /NFL /NDL /NJH /NJS /NP | Out-Null
    if ($LASTEXITCODE -ge 8) { throw "Copying the new files failed (robocopy exit code $LASTEXITCODE)." }

    Remove-Item -LiteralPath $stage -Recurse -Force -ErrorAction SilentlyContinue
    Remove-Item -LiteralPath $Zip -Force -ErrorAction SilentlyContinue
}
catch {
    Write-Output $_
    Add-Type -AssemblyName PresentationFramework
    [System.Windows.MessageBox]::Show("Norilight couldn't install the update.`n`n$_`n`nDetails are in $work\update.log", 'Norilight') | Out-Null
}
finally {
    Stop-Transcript | Out-Null
    # Portable mode is detected from the working directory
    Start-Process -FilePath $Exe -WorkingDirectory $Dest
}
)PS1";
#elif defined(Q_OS_DARWIN)
// Waits for Norilight to quit, copies the app bundle out of the DMG next to
// the old one, swaps them and opens the new app. If anything fails before the
// swap, the old app stays as it was.
static const char* k_MacUpdateScript = R"SH(#!/bin/sh
pid="$1"; dmg="$2"; app="$3"; log="$4"
exec >"$log" 2>&1
set -x
while kill -0 "$pid" 2>/dev/null; do sleep 0.5; done

mnt="$(mktemp -d /tmp/norilight-update.XXXXXX)"
if hdiutil attach -nobrowse -readonly -noautoopen -mountpoint "$mnt" "$dmg"; then
    src=""
    for candidate in "$mnt/"*.app; do
        if [ -d "$candidate" ]; then src="$candidate"; break; fi
    done
    rm -rf "$app.update"
    if [ -n "$src" ] && ditto "$src" "$app.update"; then
        rm -rf "$app.old"
        if mv "$app" "$app.old"; then
            if mv "$app.update" "$app"; then
                rm -rf "$app.old"
            else
                mv "$app.old" "$app"
            fi
        fi
    fi
    rm -rf "$app.update"
    hdiutil detach "$mnt" -quiet || hdiutil detach "$mnt" -force -quiet
    rm -f "$dmg"
fi
rmdir "$mnt" 2>/dev/null
xattr -dr com.apple.quarantine "$app" 2>/dev/null
open "$app"
)SH";
#endif

static QString updateWorkDir()
{
    return QDir(QDir::tempPath()).filePath(QStringLiteral("Norilight-update"));
}

// Creating a file is the only dependable writability check for folders on
// Windows, where QFileInfo::isWritable() ignores ACLs.
static bool canCreateFileIn(const QString& dir)
{
    QTemporaryFile probe(QDir(dir).filePath(QStringLiteral(".norilight-write-test-XXXXXX")));
    return probe.open();
}

#ifdef Q_OS_DARWIN
static QString macBundlePath()
{
    // .../Norilight.app/Contents/MacOS
    QDir dir(QCoreApplication::applicationDirPath());
    if (!dir.cdUp() || !dir.cdUp()) {
        return QString();
    }
    return dir.absolutePath().endsWith(QStringLiteral(".app")) ? dir.absolutePath() : QString();
}
#endif

AutoUpdateChecker::AutoUpdateChecker(QObject *parent) :
    QObject(parent),
    m_BuildSha(QStringLiteral(NORILIGHT_BUILD_SHA).trimmed().toLower()),
    m_Kind(InstallKind::None),
    m_AssetSize(-1),
    m_DownloadHash(QCryptographicHash::Sha256)
{
    m_Nam = new QNetworkAccessManager(this);

    // Never communicate over HTTP
    m_Nam->setStrictTransportSecurityEnabled(true);

    // Allow HTTP redirects (release downloads redirect to GitHub's storage host)
    m_Nam->setRedirectPolicy(QNetworkRequest::NoLessSafeRedirectPolicy);

    qDebug() << "Norilight version:" << NORILIGHT_VERSION_STR << "commit:" << (m_BuildSha.isEmpty() ? QStringLiteral("unknown") : m_BuildSha);
}

AutoUpdateChecker::InstallKind AutoUpdateChecker::detectInstallKind()
{
#if defined(Q_OS_WIN32)
    QDir appDir(QCoreApplication::applicationDirPath());
    if (appDir.exists(QStringLiteral("unins000.exe")) && !appDir.exists(QStringLiteral("portable.dat"))) {
        return InstallKind::WindowsInstaller;
    }
    // A ZIP extracted somewhere we can't write (Program Files, a read-only
    // share) is updated by hand
    return canCreateFileIn(appDir.absolutePath()) ? InstallKind::WindowsPortable : InstallKind::None;
#elif defined(Q_OS_DARWIN)
    return macBundlePath().isEmpty() ? InstallKind::None : InstallKind::MacDmg;
#else
    return InstallKind::None;
#endif
}

void AutoUpdateChecker::start()
{
    if (m_BuildSha.isEmpty()) {
        qDebug() << "Not a nightly build; skipping the update check";
        return;
    }

#if defined(Q_OS_WIN32) || defined(Q_OS_DARWIN)
    m_Kind = detectInstallKind();

    QNetworkRequest request(QUrl(QString::fromLatin1(k_NightlyReleaseUrl)));
    // GitHub's API rejects requests without a User-Agent
    request.setHeader(QNetworkRequest::UserAgentHeader, QStringLiteral("Norilight-UpdateChecker"));
    request.setRawHeader("Accept", "application/vnd.github+json");
    request.setAttribute(QNetworkRequest::Http2AllowedAttribute, true);

    QNetworkReply* reply = m_Nam->get(request);
    connect(reply, &QNetworkReply::finished, this, [this, reply]() {
        handleUpdateCheckRequestFinished(reply);
    });
#endif
}

QString AutoUpdateChecker::releaseUrl() const
{
    return QString::fromLatin1(k_NightlyReleasePage);
}

bool AutoUpdateChecker::canInstall() const
{
    return m_Kind != InstallKind::None && !m_AssetUrl.isEmpty();
}

void AutoUpdateChecker::handleUpdateCheckRequestFinished(QNetworkReply* reply)
{
    Q_ASSERT(reply->isFinished());
    reply->deleteLater();

    if (reply->error() != QNetworkReply::NoError) {
        // A 404 happens briefly while the workflow replaces the release
        qWarning() << "Update check failed:" << reply->error() << reply->errorString();
        return;
    }

    QJsonParseError error;
    QJsonDocument doc = QJsonDocument::fromJson(reply->readAll(), &error);
    if (!doc.isObject()) {
        qWarning() << "Nightly release info malformed:" << error.errorString();
        return;
    }

    QJsonObject release = doc.object();
    QString targetSha = release["target_commitish"].toString().trimmed().toLower();
    if (targetSha.isEmpty()) {
        qWarning() << "Nightly release has no target commit";
        return;
    }

    // The release targets a full SHA; tolerate short SHAs on either side
    if (targetSha.startsWith(m_BuildSha) || m_BuildSha.startsWith(targetSha)) {
        qDebug() << "Running the latest nightly";
        return;
    }

    // "Nightly (nightly-20261115-abc1234)" -> "nightly-20261115-abc1234"
    QString version = release["name"].toString();
    int open = version.indexOf('(');
    int close = version.lastIndexOf(')');
    if (open >= 0 && close > open) {
        version = version.mid(open + 1, close - open - 1);
    }
    if (version.isEmpty()) {
        version = targetSha.left(7);
    }

    // Pick the download that matches how this copy was installed. Without an
    // in-app install, Windows users get the installer in their browser.
    auto matches = [this](const QString& name) {
        switch (m_Kind) {
        case InstallKind::WindowsPortable:
            return name.startsWith(QStringLiteral("Norilight-Windows-x64"), Qt::CaseInsensitive) &&
                   name.endsWith(QStringLiteral(".zip"), Qt::CaseInsensitive);
        case InstallKind::MacDmg:
            return name.endsWith(QStringLiteral(".dmg"), Qt::CaseInsensitive);
        case InstallKind::WindowsInstaller:
        case InstallKind::None:
        default:
#if defined(Q_OS_WIN32)
            return name.endsWith(QStringLiteral("-Setup.exe"), Qt::CaseInsensitive);
#elif defined(Q_OS_DARWIN)
            return name.endsWith(QStringLiteral(".dmg"), Qt::CaseInsensitive);
#else
            Q_UNUSED(name);
            return false;
#endif
        }
    };

    const QJsonArray assets = release["assets"].toArray();
    for (const auto& asset : assets) {
        QJsonObject assetObj = asset.toObject();
        QString name = assetObj["name"].toString();
        if (!matches(name)) {
            continue;
        }

        m_AssetName = name;
        m_AssetUrl = assetObj["browser_download_url"].toString();
        m_AssetSize = static_cast<qint64>(assetObj["size"].toDouble(-1));

        // GitHub publishes "sha256:<hex>" for every release asset
        QString digest = assetObj["digest"].toString();
        if (digest.startsWith(QStringLiteral("sha256:"), Qt::CaseInsensitive)) {
            m_AssetSha256 = QByteArray::fromHex(digest.mid(7).toLatin1());
        }
        break;
    }

    // The file name becomes part of a local path; refuse anything odd
    if (m_AssetName.contains('/') || m_AssetName.contains('\\') || m_AssetName.contains(QStringLiteral(".."))) {
        m_AssetName.clear();
        m_AssetUrl.clear();
    }

    emit updateInfoChanged();

    qDebug() << "Newer nightly available:" << version << downloadUrl() << "in-app install:" << canInstall();
    emit onUpdateAvailable(version, downloadUrl());
}

void AutoUpdateChecker::installUpdate()
{
    if (m_Download) {
        return;
    }
    if (!canInstall()) {
        emit installFailed(tr("This copy of Norilight can't update itself."));
        return;
    }

    QDir workDir(updateWorkDir());
    workDir.removeRecursively();
    if (!QDir().mkpath(workDir.absolutePath())) {
        emit installFailed(tr("Norilight couldn't create a folder for the download."));
        return;
    }

    m_DownloadFile.setFileName(workDir.filePath(m_AssetName));
    if (!m_DownloadFile.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
        emit installFailed(tr("Norilight couldn't save the download: %1").arg(m_DownloadFile.errorString()));
        return;
    }
    m_DownloadHash.reset();

    QNetworkRequest request{QUrl(m_AssetUrl)};
    request.setHeader(QNetworkRequest::UserAgentHeader, QStringLiteral("Norilight-Updater"));
    request.setAttribute(QNetworkRequest::Http2AllowedAttribute, true);

    m_Download = m_Nam->get(request);
    connect(m_Download, &QNetworkReply::readyRead, this, &AutoUpdateChecker::handleDownloadReadyRead);
    connect(m_Download, &QNetworkReply::finished, this, &AutoUpdateChecker::handleDownloadFinished);
    connect(m_Download, &QNetworkReply::downloadProgress, this, [this](qint64 received, qint64 total) {
        emit downloadProgress(received, total > 0 ? total : m_AssetSize);
    });

    qInfo() << "Downloading update" << m_AssetUrl << "to" << m_DownloadFile.fileName();
    emit busyChanged();
    emit downloadProgress(0, m_AssetSize);
}

void AutoUpdateChecker::cancelInstall()
{
    if (m_Download) {
        // handleDownloadFinished() sees OperationCanceledError and cleans up
        m_Download->abort();
    }
}

void AutoUpdateChecker::handleDownloadReadyRead()
{
    if (!m_Download) {
        return;
    }

    QByteArray data = m_Download->readAll();
    m_DownloadHash.addData(data);
    if (m_DownloadFile.write(data) != data.size()) {
        m_Download->abort();
    }
}

void AutoUpdateChecker::failInstall(const QString& message)
{
    qWarning() << "Update failed:" << message;
    if (m_DownloadFile.isOpen()) {
        m_DownloadFile.close();
    }
    m_DownloadFile.remove();
    emit installFailed(message);
}

void AutoUpdateChecker::handleDownloadFinished()
{
    QNetworkReply* reply = m_Download;
    if (!reply) {
        return;
    }

    // Collect anything that arrived with the final notification
    handleDownloadReadyRead();

    m_Download = nullptr;
    reply->deleteLater();
    emit busyChanged();

    if (reply->error() == QNetworkReply::OperationCanceledError) {
        // Cancelled from the dialog, or the disk filled up
        bool writeFailed = m_DownloadFile.error() != QFileDevice::NoError;
        QString writeError = m_DownloadFile.errorString();
        m_DownloadFile.close();
        m_DownloadFile.remove();
        if (writeFailed) {
            emit installFailed(tr("Norilight couldn't save the download: %1").arg(writeError));
        }
        return;
    }
    if (reply->error() != QNetworkReply::NoError) {
        failInstall(tr("The download failed: %1").arg(reply->errorString()));
        return;
    }

    finishDownload();
}

void AutoUpdateChecker::finishDownload()
{
    if (!m_DownloadFile.flush()) {
        failInstall(tr("Norilight couldn't save the download: %1").arg(m_DownloadFile.errorString()));
        return;
    }
    qint64 size = m_DownloadFile.size();
    m_DownloadFile.close();

    if (m_AssetSize > 0 && size != m_AssetSize) {
        failInstall(tr("The download is incomplete (%1 of %2 bytes). Please try again.").arg(size).arg(m_AssetSize));
        return;
    }
    if (!m_AssetSha256.isEmpty() && m_DownloadHash.result() != m_AssetSha256) {
        failInstall(tr("The download doesn't match the release's checksum, so it wasn't installed. Please try again."));
        return;
    }

    QString error;
    if (!launchInstaller(error)) {
        failInstall(error);
        return;
    }

    qInfo() << "Update handed to the installer; waiting for the app to quit";
    emit installerStarted();
}

bool AutoUpdateChecker::launchInstaller(QString& error)
{
    const QString file = QDir::toNativeSeparators(m_DownloadFile.fileName());
    const QString pid = QString::number(QCoreApplication::applicationPid());

    switch (m_Kind) {
#if defined(Q_OS_WIN32)
    case InstallKind::WindowsInstaller: {
        // Run unelevated and let Setup ask for elevation itself, so it can
        // start Norilight again as the signed-in user rather than as admin.
        // /RELAUNCH=1 is read by norilight-installer.iss.
        std::wstring fileW = file.toStdWString();
        std::wstring paramsW = QStringLiteral("/SILENT /SUPPRESSMSGBOXES /NORESTART /CLOSEAPPLICATIONS /RELAUNCH=1").toStdWString();

        SHELLEXECUTEINFOW info = {};
        info.cbSize = sizeof(info);
        info.fMask = SEE_MASK_NOASYNC;
        info.lpVerb = L"open";
        info.lpFile = fileW.c_str();
        info.lpParameters = paramsW.c_str();
        info.nShow = SW_SHOWNORMAL;
        if (!ShellExecuteExW(&info)) {
            error = tr("The installer couldn't be started (error %1).").arg(GetLastError());
            return false;
        }
        return true;
    }
    case InstallKind::WindowsPortable: {
        QString script = QDir(updateWorkDir()).filePath(QStringLiteral("apply-update.ps1"));
        QFile scriptFile(script);
        // Windows PowerShell reads scripts without a BOM in the ANSI code page
        if (!scriptFile.open(QIODevice::WriteOnly | QIODevice::Truncate) ||
                scriptFile.write("\xEF\xBB\xBF") != 3 ||
                scriptFile.write(k_PortableUpdateScript) < 0) {
            error = tr("Norilight couldn't prepare the update: %1").arg(scriptFile.errorString());
            return false;
        }
        scriptFile.close();

        const QString appDir = QDir::toNativeSeparators(QCoreApplication::applicationDirPath());
        const QString exe = QDir::toNativeSeparators(QCoreApplication::applicationFilePath());
        QStringList args = {
            QStringLiteral("-NoProfile"), QStringLiteral("-NonInteractive"),
            QStringLiteral("-ExecutionPolicy"), QStringLiteral("Bypass"),
            QStringLiteral("-WindowStyle"), QStringLiteral("Hidden"),
            QStringLiteral("-File"), QDir::toNativeSeparators(script),
            QStringLiteral("-WaitPid"), pid,
            QStringLiteral("-Zip"), file,
            QStringLiteral("-Dest"), appDir,
            QStringLiteral("-Exe"), exe,
        };
        if (!QProcess::startDetached(QStringLiteral("powershell.exe"), args, QDir::tempPath())) {
            error = tr("Norilight couldn't start the update helper.");
            return false;
        }
        return true;
    }
#elif defined(Q_OS_DARWIN)
    case InstallKind::MacDmg: {
        QString bundle = macBundlePath();
        QFileInfo bundleParent(QFileInfo(bundle).absolutePath());

        // Without write access to the app's folder, open the DMG so the
        // user can drag the new app over (macOS asks for a password then)
        if (!canCreateFileIn(bundleParent.absoluteFilePath())) {
            if (!QDesktopServices::openUrl(QUrl::fromLocalFile(file))) {
                error = tr("Norilight couldn't open the downloaded disk image.");
                return false;
            }
            return true;
        }

        QString script = QDir(updateWorkDir()).filePath(QStringLiteral("apply-update.sh"));
        QFile scriptFile(script);
        if (!scriptFile.open(QIODevice::WriteOnly | QIODevice::Truncate) || scriptFile.write(k_MacUpdateScript) < 0) {
            error = tr("Norilight couldn't prepare the update: %1").arg(scriptFile.errorString());
            return false;
        }
        scriptFile.close();

        QStringList args = { script, pid, file, bundle, QDir(updateWorkDir()).filePath(QStringLiteral("update.log")) };
        if (!QProcess::startDetached(QStringLiteral("/bin/sh"), args, QDir::tempPath())) {
            error = tr("Norilight couldn't start the update helper.");
            return false;
        }
        return true;
    }
#endif
    default:
        Q_UNUSED(file);
        Q_UNUSED(pid);
        error = tr("This copy of Norilight can't update itself.");
        return false;
    }
}
